package io.github.ningpp.compat;

/**
 * Replacement for System.Buffers.BuffersExtensions (generated by CSharpToJava converter).
 */
public final class BuffersExtensions {
    private BuffersExtensions() {
    }

    /** Mirrors BuffersExtensions.CopyTo(ReadOnlySequence&lt;T&gt;, Span&lt;T&gt;) — copies the sequence into the span. */
    public static <T> void copyTo(ReadOnlySequence<T> sequence, Span<T> destination) {
        ReadOnlyMemory<T> first = sequence.getFirst();
        ReadOnlySpan<T> span = first.getSpan();
        int len = Math.min(span.length(), destination.length());
        for (int i = 0; i < len; i++) {
            destination.set(i, span.get(i));
        }
    }

    /** Mirrors BuffersExtensions.CopyTo(ReadOnlySequence&lt;T&gt;, ReadOnlySpan&lt;T&gt;) — read-only destination variant. */
    public static <T> void copyTo(ReadOnlySequence<T> sequence, ReadOnlySpan<T> destination) {
        ReadOnlyMemory<T> first = sequence.getFirst();
        ReadOnlySpan<T> span = first.getSpan();
        int len = Math.min(span.length(), destination.length());
        for (int i = 0; i < len; i++) {
            destination.set(i, span.get(i));
        }
    }

    /** Mirrors BuffersExtensions.ToArray(ReadOnlySequence&lt;T&gt;). */
    public static <T> T[] toArray(ReadOnlySequence<T> sequence) {
        return sequence.getFirst().toArray();
    }

    /** Mirrors BuffersExtensions.ToArray(ReadOnlySequence&lt;byte&gt;) — byte[] per the C# contract. */
    public static byte[] toByteArray(ReadOnlySequence<Integer> sequence) {
        return sequence.getFirst().toByteArray();
    }
}
